package bz.tikitmasta.customer;
import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.google.android.material.button.MaterialButton;import org.json.*;import java.text.SimpleDateFormat;import java.util.*;
public class MainActivity extends AppCompatActivity{final int P=Color.rgb(91,33,182),D=Color.rgb(31,22,48),G=Color.rgb(245,158,11),M=Color.rgb(105,96,120);LinearLayout root;ApiClient api=new ApiClient();int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}TextView tx(String s,int z,int c,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);if(b)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}MaterialButton bt(String s,int c,View.OnClickListener l){MaterialButton b=new MaterialButton(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTextSize(15);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(c));b.setCornerRadius(dp(14));b.setOnClickListener(l);return b;}LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(18),dp(18),dp(18),dp(18));c.setBackground(bg(Color.WHITE,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(7));c.setLayoutParams(p);return c;}void add(View v){root.addView(v);}void gap(int n){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(1,dp(n)));add(s);}@Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(D);getWindow().setNavigationBarColor(D);home();}void page(String title,String sub){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(Color.rgb(248,247,252));root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(20),dp(28),dp(20),dp(70));sc.addView(root);LinearLayout brand=new LinearLayout(this);TextView logo=tx("TM",18,Color.WHITE,true);logo.setGravity(Gravity.CENTER);logo.setBackground(bg(P,15));brand.addView(logo,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView name=tx("  TIKIT MASTA",22,D,true);name.setGravity(Gravity.CENTER_VERTICAL);brand.addView(name);add(brand);gap(25);add(tx(title,29,D,true));add(tx(sub,15,M,false));gap(18);setContentView(sc);}void home(){page("Find your next experience","Discover live events across Belize, buy securely and keep your tickets together.");LinearLayout hero=card();hero.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{P,Color.rgb(126,53,205)}));hero.addView(tx("Events made easy",24,Color.WHITE,true));hero.addView(tx("Browse real-time ticket availability from Tikit Masta.",15,Color.WHITE,false));hero.addView(bt("Explore events",G,v->events()));add(hero);gap(12);add(bt("Sign in to my account",P,v->open("/web/login?redirect=/my")));add(bt("Create an account",D,v->open("/bz/signup")));add(bt("My tickets and wallet",P,v->open("/my")));add(bt("Forgot password",D,v->open("/bz/account/forgot")));}void events(){page("Upcoming events","Live availability from tikitmaster.com");TextView load=tx("Loading events…",15,M,false);add(load);api.post("/bz_eventpass/api/v1/events",new JSONObject(),(r,e)->runOnUiThread(()->{root.removeView(load);if(e!=null||r==null||!r.optBoolean("ok")){add(tx("Unable to load events: "+(e!=null?e:"API error"),15,Color.RED,false));return;}JSONArray a=r.optJSONArray("events");for(int i=0;a!=null&&i<a.length();i++){JSONObject x=a.optJSONObject(i);LinearLayout c=card();c.addView(tx(x.optString("name"),21,D,true));c.addView(tx(date(x.optString("start_datetime"))+"\n"+x.optString("venue_name")+" • "+x.optString("city"),14,M,false));c.addView(tx(x.optString("availability").toUpperCase(Locale.US),11,Color.rgb(16,145,82),true));c.addView(bt("View and buy tickets",P,v->open(x.optString("public_url"))));root.addView(c,Math.max(3,root.getChildCount()));}add(bt("Back",D,v->home()));}));}String date(String s){try{return new SimpleDateFormat("EEE, MMM d • h:mm a",Locale.US).format(new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US).parse(s));}catch(Exception e){return s;}}void open(String p){startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(api.absolute(p))));}}
